"""Packing slip generation and fulfilment operations."""

from __future__ import annotations

from typing import Any

from orders.application.catalog_service import CatalogService
from orders.application.customer_service import CustomerService
from orders.application.errors import Conflict
from orders.application.order_service import OrderService


class FulfilmentService:
    def __init__(self, order_service: OrderService, customer_service: CustomerService,
                 catalog_service: CatalogService) -> None:
        self._order_service = order_service
        self._customer_service = customer_service
        self._catalog_service = catalog_service

    def get_packing_slip(self, order_id: str) -> dict[str, Any]:
        order = self._order_service.get_order(order_id)
        if order.status == "cancelled":
            raise Conflict("order is cancelled")

        customer = self._customer_service.get(order.customer_id)

        lines = []
        for item in order.items:
            product = self._catalog_service.get_product(item.sku)
            lines.append({
                "sku": item.sku,
                "name": product.name,
                "quantity": item.quantity,
            })

        return {
            "order_id": order.order_id,
            "customer_name": customer.name,
            "lines": lines,
        }

    def get_low_stock(self, threshold: int) -> dict[str, Any]:
        products = self._catalog_service.list_active()
        low_stock = []
        for product in products:
            on_hand = self._catalog_service.on_hand(product.sku)
            if on_hand < threshold:
                low_stock.append({
                    "sku": product.sku,
                    "name": product.name,
                    "on_hand": on_hand,
                })
        low_stock.sort(key=lambda p: (p["on_hand"], p["sku"]))
        return {"products": low_stock}

